{
 "app_name": "spotify",
 "api_name": "show_song_privates",
 "path": "/songs/{song_id}/privates",
 "method": "GET",
 "description": "Show information about the song that is private to the user.",
 "parameters": [
  {
   "name": "song_id",
   "type": "integer",
   "required": true,
   "description": "The song id to retrieve.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from spotify app login.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "liked": true,
   "reviewed": true,
   "in_song_library": true,
   "downloaded": true
  },
  "failure": {
   "message": "string"
  }
 }
}

